mapper.select:
select * from cr_report_score

    `status` != 4

        and `status` = #{listQuery.status}


        and `subject` = #{listQuery.subject}


        and `submit_time` >= #{listQuery.startTime}


        and `submit_time` <= #{listQuery.endTime}



        and (`user_name` like #{name} or `report_name` like #{name})


order by `submit_time` desc

select report_name, user_name as team_name, score_time, score from cr_report_score

    `score_time` is not null and `status` = 2

        and `subject` = #{listQuery.subject}

select * from cr_report_score

    `user_id` = #{userId}

        and `status` = #{listQuery.status}


        and `subject` = #{listQuery.subject}



        and `report_name` like #{name}


order by `submit_time` desc

select `status`, count(`status`) as count
from cr_report_score
where `user_id` = #{userId}
GROUP BY `status`;

select *
from cr_report_score
where user_id = #{userId}
  and report_name = #{reportName}
